import{_ as a,o as n,c as s,aS as t}from"./chunks/framework.DsJaIkSj.js";const m=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"01-architecture.md","filePath":"01-architecture.md","lastUpdated":null}'),r={name:"01-architecture.md"};function p(o,e,i,c,l,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><h2 id="架构原则" tabindex="-1">架构原则 <a class="header-anchor" href="#架构原则" aria-label="Permalink to &quot;架构原则&quot;">​</a></h2><p>本仓库按职责理解为基础视觉/运行时、schema/adapter、后台 patterns、业务公共模块和业务消费者几层。它们用于解释依赖方向，不是对当前源码施加不存在的强制目录模板；任何具体依赖仍以源码、包元数据和测试为准。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础视觉与运行时（ui、hooks、admin-theme、admin-framework）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>schema / adapter（form、table-schema、table）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>后台 patterns（admin-shell、admin-patterns）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>业务公共模块（pickers、product-preview、qy-address-dialog）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>业务消费者（qy-permission、qy-origin-app；qy-workspace 为旧行为证据）</span></span></code></pre></div><p>依赖应尽量朝更稳定的基础能力流动。不要为了图中的层级伪造源码中不存在的依赖，也不要把消费者的业务规则倒灌为公共包契约。</p><h2 id="公开-interface-与-exports" tabindex="-1">公开 interface 与 exports <a class="header-anchor" href="#公开-interface-与-exports" aria-label="Permalink to &quot;公开 interface 与 exports&quot;">​</a></h2><p>新公共 interface 必须使用 Qy 自有类型和语义。不得新增 Element Plus 类型、组件实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> CSS 变量泄漏为业务必须了解的接口。既有底层类型泄漏是渐进治理对象，不能在文档治理任务中被宣称为已修复。</p><p>每个包的 <code>package.json</code>、exports、源码、测试和发布产物共同决定当前可用入口；包 README 负责快速使用说明。不要在根级或架构文档复制所有包版本，也不要只根据 README 推断真实 exports。</p><h2 id="runtime-与-renderer-adapter" tabindex="-1">runtime 与 renderer/adapter <a class="header-anchor" href="#runtime-与-renderer-adapter" aria-label="Permalink to &quot;runtime 与 renderer/adapter&quot;">​</a></h2><p>当前主 implementation 是 Vue 3 + Element Plus。Element Plus 可以存在于 implementation 内部，但业务长期依赖 Qy interface、Qy schema、Qy tokens 和宿主 runtime。仓库当前不宣称多框架或多 renderer 支持。</p><p>不要求简单模块都创建物理 renderer 目录。仅在复杂受控状态、浮层/teleport/focus、递归节点、厂商回调对象、底层默认行为与 Qy 契约不同，或出现第二个真实实现时，为该模块明确内部 adapter seam。是否独立分包、增加构建入口或注册 adapter，要等真实消费者需求出现后由 ADR 决定。</p><h2 id="主题与发布" tabindex="-1">主题与发布 <a class="header-anchor" href="#主题与发布" aria-label="Permalink to &quot;主题与发布&quot;">​</a></h2><p>Qy tokens 是长期视觉协议；<code>--el-*</code> 仅可作为当前 implementation 内部映射，不能成为业务侧必须使用的公共主题接口。</p><p>发布事实由各包 <code>package.json</code> 与 release record 决定。消费者通过正式 npm 包使用时遵循其声明的依赖与 lockfile；需要本地联调时，消费者必须显式配置其解析到源码入口或构建产物的方式，不能把临时 alias 当作默认发布契约。</p><h2 id="消费者关系" tabindex="-1">消费者关系 <a class="header-anchor" href="#消费者关系" aria-label="Permalink to &quot;消费者关系&quot;">​</a></h2><p><code>qy-permission</code>、<code>qy-origin-app</code> 与 <code>qy-workspace</code> 分别承担后台标准页/权限消费、录单与业务公共包消费、旧 ERP 证据与迁移来源的角色。消费者文档记录接入和迁移证据，不替代本仓库的架构权威，也不决定其他消费者的实际安装版本。</p><p>返回 <a href="./README">文档地图</a> 查看阅读顺序和文档状态。</p>`,17)])])}const u=a(r,[["render",p]]);export{m as __pageData,u as default};
